/**
 * 零依赖静态预览服务器（仅需 Node.js）。
 * 托管 dist/，并对 Vue Router history 回退到 index.html。
 */
import http from 'node:http'
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const rootDir = path.resolve(__dirname, '..')
const distDir = path.join(rootDir, 'dist')
const preferredPort = Number(process.env.PORT || process.argv[2] || 1111)
const openBrowser = !process.argv.includes('--no-open')

const mimeTypes = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.webp': 'image/webp',
  '.ico': 'image/x-icon',
  '.woff': 'font/woff',
  '.woff2': 'font/woff2',
  '.map': 'application/json; charset=utf-8',
}

function send(res, status, body, headers = {}) {
  res.writeHead(status, headers)
  res.end(body)
}

function safeJoin(base, requestPath) {
  const decoded = decodeURIComponent(requestPath.split('?')[0])
  const normalized = path.normalize(decoded).replace(/^([/\\])+/, '')
  const full = path.join(base, normalized)
  if (!full.startsWith(base)) return null
  return full
}

function contentType(filePath) {
  return mimeTypes[path.extname(filePath).toLowerCase()] || 'application/octet-stream'
}

async function tryListen(port) {
  for (let candidate = port; candidate <= port + 20; candidate += 1) {
    try {
      await new Promise((resolve, reject) => {
        const probe = http.createServer()
        probe.once('error', reject)
        probe.listen(candidate, '127.0.0.1', () => {
          probe.close((err) => (err ? reject(err) : resolve(candidate)))
        })
      })
      return candidate
    } catch {
      // try next
    }
  }
  throw new Error(`No available port from ${port}`)
}

function openUrl(url) {
  const { exec } = awaitImportChildProcess()
  if (process.platform === 'win32') {
    exec(`cmd /c start "" "${url}"`)
  } else if (process.platform === 'darwin') {
    exec(`open "${url}"`)
  } else {
    exec(`xdg-open "${url}"`)
  }
}

function awaitImportChildProcess() {
  // sync require-like for child_process without top-level await timing issues
  return import('node:child_process').then((m) => m)
}

async function main() {
  if (!fs.existsSync(path.join(distDir, 'index.html'))) {
    console.error('[error] dist/index.html not found.')
    console.error('Please run: npm install && npm run build')
    process.exit(1)
  }

  const port = await tryListen(preferredPort)
  const url = `http://127.0.0.1:${port}/`

  const server = http.createServer((req, res) => {
    const urlPath = req.url || '/'
    let filePath = safeJoin(distDir, urlPath === '/' ? '/index.html' : urlPath)

    if (!filePath) {
      send(res, 403, 'Forbidden')
      return
    }

    fs.stat(filePath, (err, stat) => {
      if (!err && stat.isDirectory()) {
        filePath = path.join(filePath, 'index.html')
      }

      fs.readFile(filePath, (readErr, data) => {
        if (!readErr) {
          send(res, 200, data, {
            'Content-Type': contentType(filePath),
            'Cache-Control': 'no-cache',
          })
          return
        }

        // SPA fallback
        const indexPath = path.join(distDir, 'index.html')
        fs.readFile(indexPath, (indexErr, indexData) => {
          if (indexErr) {
            send(res, 404, 'Not Found')
            return
          }
          send(res, 200, indexData, {
            'Content-Type': 'text/html; charset=utf-8',
            'Cache-Control': 'no-cache',
          })
        })
      })
    })
  })

  server.listen(port, '127.0.0.1', async () => {
    console.log('')
    console.log('============================================================')
    console.log(' AoQin Demo — Static Preview')
    console.log('============================================================')
    console.log(`URL: ${url}`)
    if (port !== preferredPort) {
      console.log(`Port ${preferredPort} busy, using ${port}.`)
    }
    console.log('Press Ctrl+C to stop.')
    console.log('')

    if (openBrowser) {
      try {
        const { exec } = await import('node:child_process')
        if (process.platform === 'win32') {
          exec(`cmd /c start "" "${url}"`)
        } else if (process.platform === 'darwin') {
          exec(`open "${url}"`)
        } else {
          exec(`xdg-open "${url}"`)
        }
      } catch (e) {
        console.warn('[warn] Could not open browser automatically:', e.message)
      }
    }
  })
}

main().catch((err) => {
  console.error(err)
  process.exit(1)
})

