  Write-Host '[error] dist/index.html not found. Ask sender for a complete package.' -ForegroundColor Red
  exit 1
}

$MimeMap = @{
  '.html' = 'text/html; charset=utf-8'
  '.js'   = 'text/javascript; charset=utf-8'
  '.css'  = 'text/css; charset=utf-8'
  '.json' = 'application/json; charset=utf-8'
  '.svg'  = 'image/svg+xml'
  '.png'  = 'image/png'
  '.jpg'  = 'image/jpeg'
  '.jpeg' = 'image/jpeg'
  '.gif'  = 'image/gif'
  '.webp' = 'image/webp'
  '.ico'  = 'image/x-icon'
  '.woff' = 'font/woff'
  '.woff2'= 'font/woff2'
  '.ttf'  = 'font/ttf'
  '.map'  = 'application/json; charset=utf-8'
}

function Get-FreePort {
  param([int]$Preferred)
  foreach ($candidate in $Preferred..($Preferred + 20)) {
    $listener = New-Object System.Net.Sockets.TcpListener ([System.Net.IPAddress]::Loopback), $candidate
    try {
      $listener.Start()
      $listener.Stop()
      return $candidate
    } catch {
      # busy
    } finally {
      try { $listener.Stop() } catch {}
    }
  }
  throw "No free port from $Preferred"
}

function Get-ContentType {
  param([string]$Path)
  $ext = [System.IO.Path]::GetExtension($Path).ToLowerInvariant()
  if ($MimeMap.ContainsKey($ext)) { return $MimeMap[$ext] }
  return 'application/octet-stream'
}

function Resolve-SafePath {
  param([string]$RequestPath)
  $raw = [Uri]::UnescapeDataString(($RequestPath -split '\?')[0])
  if ([string]::IsNullOrWhiteSpace($raw) -or $raw -eq '/') {
    return $IndexPath
  }
  $trimmed = $raw.TrimStart('/').Replace('/', [IO.Path]::DirectorySeparatorChar)
  $full = [System.IO.Path]::GetFullPath((Join-Path $DistDir $trimmed))
  if (-not $full.StartsWith($DistDir, [System.StringComparison]::OrdinalIgnoreCase)) {
    return $null
  }
  if (Test-Path -LiteralPath $full -PathType Container) {
    $full = Join-Path $full 'index.html'
  }
  if (Test-Path -LiteralPath $full -PathType Leaf) {
    return $full
  }
  return $IndexPath
}

$ResolvedPort = Get-FreePort -Preferred $Port
$Prefix = "http://127.0.0.1:$ResolvedPort/"
$Url = $Prefix

$Http = New-Object System.Net.HttpListener
$Http.Prefixes.Add($Prefix)
try {
  $Http.Start()
} catch {
  Write-Host '[error] Failed to start local preview server.' -ForegroundColor Red
  Write-Host $_.Exception.Message -ForegroundColor Yellow
  Write-Host 'Tip: close other demo windows, or reboot once, then retry.' -ForegroundColor Yellow
  exit 1
}

