Write-Host ' AoQin Demo — Static Preview (No Node.js)' -ForegroundColor Cyan
Write-Host '============================================================' -ForegroundColor Cyan
Write-Host " URL: $Url" -ForegroundColor Green
if ($ResolvedPort -ne $Port) {
  Write-Host " Port $Port busy, using $ResolvedPort." -ForegroundColor Yellow
}
Write-Host ' Keep this window open. Close it to stop.' -ForegroundColor Yellow
Write-Host '============================================================' -ForegroundColor Cyan
Write-Host ''

if (-not $NoOpen) {
  Start-Process $Url
}

try {
  while ($Http.IsListening) {
    $context = $Http.GetContext()
    $request = $context.Request
    $response = $context.Response
    try {
      $filePath = Resolve-SafePath -RequestPath $request.Url.AbsolutePath
      if (-not $filePath) {
        $response.StatusCode = 403
        $bytes = [Text.Encoding]::UTF8.GetBytes('Forbidden')
        $response.OutputStream.Write($bytes, 0, $bytes.Length)
      } else {
        $bytes = [System.IO.File]::ReadAllBytes($filePath)
        $response.StatusCode = 200
        $response.ContentType = Get-ContentType -Path $filePath
        $response.Headers['Cache-Control'] = 'no-cache'
        $response.ContentLength64 = $bytes.LongLength
        $response.OutputStream.Write($bytes, 0, $bytes.Length)
      }
    } catch {
      try {
        $response.StatusCode = 500
      } catch {}
    } finally {
      try { $response.OutputStream.Close() } catch {}
      try { $response.Close() } catch {}
    }
  }
} finally {
  if ($Http.IsListening) { $Http.Stop() }
  $Http.Close()
}

param(
  [int]$Port = 1111,
  [switch]$NoOpen,
  [switch]$ForceBuild
)

$ErrorActionPreference = 'Stop'
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
$OutputEncoding = [System.Text.Encoding]::UTF8

$ScriptDir = Split-Path -Parent $MyInvocation.MyCommand.Path
$ProjectDir = Resolve-Path (Join-Path $ScriptDir '..')
Set-Location $ProjectDir

function Test-CommandExists {
  param([string]$Name)
  return [bool](Get-Command $Name -ErrorAction SilentlyContinue)
}

$distIndex = Join-Path $ProjectDir 'dist\index.html'
$needBuild = $ForceBuild -or -not (Test-Path -LiteralPath $distIndex)
$hasSource = Test-Path -LiteralPath (Join-Path $ProjectDir 'vite.config.ts')

if ($needBuild) {
  if (-not $hasSource) {
    Write-Host '[error] Missing dist/. This package is incomplete.' -ForegroundColor Red
    Write-Host 'Please ask the sender for a fresh demo zip (must include dist folder).' -ForegroundColor Yellow
    exit 1
  }

  if (-not (Test-CommandExists 'npm')) {
    Write-Host '[error] Source rebuild needs Node.js/npm (developers only).' -ForegroundColor Red
    Write-Host 'Non-tech users: use a package that already contains dist/.' -ForegroundColor Yellow
    exit 1
  }

  if (-not (Test-Path -LiteralPath (Join-Path $ProjectDir 'node_modules'))) {
    Write-Host '[info] Installing dependencies for rebuild...' -ForegroundColor Yellow
    npm install
    if ($LASTEXITCODE -ne 0) { throw 'npm install failed' }
  }

  Write-Host '[info] Building dist/ ...' -ForegroundColor Yellow
  npm run build
  if ($LASTEXITCODE -ne 0) { throw 'npm run build failed' }
} else {
  Write-Host '[info] Found dist/. Starting local preview (no Node.js needed).' -ForegroundColor Green
}

$serveScript = Join-Path $ScriptDir 'serve-static.ps1'
$serveArgs = @{
  Port = $Port
  DistDir = (Join-Path $ProjectDir 'dist')
}
if ($NoOpen) {
  $serveArgs['NoOpen'] = $true
}

Write-Host ''
Write-Host '============================================================' -ForegroundColor Cyan
Write-Host ' AoQin Reserve & Planning Demo' -ForegroundColor Cyan
Write-Host '============================================================' -ForegroundColor Cyan
Write-Host ' Mode: static preview (Windows PowerShell, no install)' -ForegroundColor Green
Write-Host ' Data: local sample / Mock only (not production backend)' -ForegroundColor Yellow
Write-Host '============================================================' -ForegroundColor Cyan
Write-Host ''

& $serveScript @serveArgs

@echo off
cd /d "%~dp0"
call "%~dp0`1-启动演示.cmd"

param(
  [string]$OutDir = ''
)

$ErrorActionPreference = 'Stop'
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
$OutputEncoding = [System.Text.Encoding]::UTF8

$ScriptDir = Split-Path -Parent $MyInvocation.MyCommand.Path
$ProjectDir = Resolve-Path (Join-Path $ScriptDir '..')
Set-Location $ProjectDir

if (-not $OutDir) {
  $stamp = Get-Date -Format 'yyyyMMdd-HHmm'
  $OutDir = Join-Path (Split-Path $ProjectDir -Parent) "frontend-demo-static-$stamp"
}

Write-Host '[info] Building static dist...' -ForegroundColor Yellow
if (-not (Test-Path -LiteralPath (Join-Path $ProjectDir 'node_modules'))) {
  npm install
  if ($LASTEXITCODE -ne 0) { throw 'npm install failed' }
}
npm run build
if ($LASTEXITCODE -ne 0) { throw 'npm run build failed' }

if (Test-Path -LiteralPath $OutDir) {
  Remove-Item -LiteralPath $OutDir -Recurse -Force
}
New-Item -ItemType Directory -Path $OutDir | Out-Null

function Copy-Tree {
  param([string]$RelativePath)
  $src = Join-Path $ProjectDir $RelativePath
  if (-not (Test-Path -LiteralPath $src)) {
    Write-Host "[warn] skip missing: $RelativePath" -ForegroundColor Yellow
    return
  }
  $dest = Join-Path $OutDir $RelativePath
  $destParent = Split-Path $dest -Parent
  if (-not (Test-Path -LiteralPath $destParent)) {
    New-Item -ItemType Directory -Path $destParent -Force | Out-Null
  }
  Copy-Item -LiteralPath $src -Destination $dest -Recurse -Force
  Write-Host "[copy] $RelativePath"
}

# Recipient package only (no Node / no source rebuild required)
Copy-Tree 'dist'
Copy-Tree 'scripts\serve-static.ps1'
Copy-Tree 'scripts\start-demo.ps1'

# Docs: guide + FAQ + screenshots folder if present
$docsOut = Join-Path $OutDir 'docs'
New-Item -ItemType Directory -Path $docsOut -Force | Out-Null
$docsSrc = Join-Path $ProjectDir 'docs'
if (Test-Path -LiteralPath $docsSrc) {
  Get-ChildItem -LiteralPath $docsSrc -File | ForEach-Object {
    Copy-Item -LiteralPath $_.FullName -Destination (Join-Path $docsOut $_.Name) -Force
    Write-Host "[copy] docs/$($_.Name)"
  }
  $shots = Join-Path $docsSrc 'screenshots'
  if (Test-Path -LiteralPath $shots) {
    Copy-Item -LiteralPath $shots -Destination (Join-Path $docsOut 'screenshots') -Recurse -Force
    Write-Host '[copy] docs/screenshots'
  }
}

# Launchers + recipient notes (exclude sender/dev clutter)
$excludeTxt = @(
  'SENDER-HOW-TO-PACK.txt',
  'readme.md.txt'
)
Get-ChildItem -LiteralPath $ProjectDir -File | Where-Object {
  ($_.Extension -eq '.cmd') -or ($_.Extension -eq '.txt')
} | Where-Object {
  $excludeTxt -notcontains $_.Name
} | ForEach-Object {
  Copy-Item -LiteralPath $_.FullName -Destination (Join-Path $OutDir $_.Name) -Force
  Write-Host "[copy] $($_.Name)"
}

